# Refresh the embedded Bluetooth SIG Assigned Numbers snapshot.
#
#   packaging/update-sig.sh
#
# Downloads the SIG's public company identifier, 16-bit service UUID and
# Core version registries, records their checksums and today's date, and
# hands them to the generator in crates/monas-bt/src/assigned.rs, which rewrites
# crates/monas-bt/src/sig_numbers.tsv. The snapshot is only ever this script's
# output: a file generated by the code that reads it is one that cannot
# disagree with it (POLICY rule 7). The same shape as update-oui.sh.
set -eu

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
BASE="https://bitbucket.org/bluetooth-SIG/public/raw/main/assigned_numbers"

DIR=$(mktemp -d)
trap 'rm -rf "$DIR"' EXIT

fetch() {
    path=$1
    top=$2
    file=$(basename "$path")
    curl --fail --silent --show-error --location --output "$DIR/$file" "$BASE/$path"
    # The registry's own top-level key, not an error page that happened to
    # come back with a 200.
    grep -q "^$top:" "$DIR/$file" || {
        echo "update-sig.sh: $file is not the SIG's registry" >&2
        exit 1
    }
    # One request at a time, a second apart: this is someone else's server.
    sleep 1
}

fetch company_identifiers/company_identifiers.yaml company_identifiers
fetch uuids/service_uuids.yaml uuids
fetch core/core_version.yaml core_version

(cd "$DIR" && sha256sum company_identifiers.yaml service_uuids.yaml core_version.yaml > SHA256SUMS)
date -u +%Y-%m-%d > "$DIR/FETCHED"

# In the classic Bluetooth crate, where the snapshot lives, and asserted to
# have run: with a name that matches nothing, cargo reports success for zero
# tests and the snapshot is never rewritten, while this script says it was.
SDRTOP_SIG_DIR="$DIR" cargo test -p monas-bt --locked --manifest-path "$ROOT/Cargo.toml" \
    -- --ignored --exact assigned::tests::regenerate_the_sig_snapshot \
    > "$DIR/test.log" 2>&1 || { cat "$DIR/test.log" >&2; exit 1; }
grep -q 'test result: ok. 1 passed' "$DIR/test.log" || {
    cat "$DIR/test.log" >&2
    echo "update-sig.sh: the generator did not run; nothing was rewritten" >&2
    exit 1
}

echo "update-sig.sh: crates/monas-bt/src/sig_numbers.tsv rewritten from the registry of $(cat "$DIR/FETCHED")"
